<script setup lang="ts">
const [{data:settingsResponse},{data:postsResponse},{data:projectsResponse}]=await Promise.all([useFetch<any>('/api/settings'),useFetch<any>('/api/posts',{query:{pageSize:4}}),useFetch<any>('/api/projects')]);const settings=computed(()=>settingsResponse.value.data);const posts=computed(()=>postsResponse.value.data.items);const projects=computed(()=>projectsResponse.value.data.slice(0,settings.value.featuredProjectCount));useSeoMeta({title:()=>settings.value.seo.title||settings.value.siteName,description:()=>settings.value.seo.description||settings.value.siteDescription,ogImage:()=>settings.value.seo.ogImage||undefined})
</script>
<template><div class="home"><section class="hero"><p class="eyebrow">{{settings.currentStatus}}</p><h1>你好，我是 {{settings.personName}}。</h1><p class="lead">{{settings.bio}}</p><div class="tech"><span v-for="item in settings.techStack" :key="item">{{item}}</span></div></section><section><div class="section-head"><h2>最近文章</h2><NuxtLink to="/blog">查看全部 →</NuxtLink></div><div class="recent"><NuxtLink v-for="post in posts" :key="post.id" :to="`/blog/${post.id}`"><div><strong>{{post.title}}</strong><p>{{post.summary}}</p></div><time>{{new Date(post.publishedAt).toLocaleDateString('zh-CN')}}</time></NuxtLink></div></section><section v-if="projects.length"><div class="section-head"><h2>精选项目</h2><NuxtLink to="/projects">查看全部 →</NuxtLink></div><div class="home-projects"><a v-for="p in projects" :key="p.id" :href="p.websiteUrl||p.githubUrl" target="_blank" rel="noopener noreferrer"><strong>{{p.name}}</strong><p>{{p.summary}}</p></a></div></section></div></template>
